'use strict';
const OperationConfirm={queue:Promise.resolve(),ask(options){const run=()=>new Promise(resolve=>{const trigger=document.activeElement,box=document.createElement('dialog');box.className='operation-confirm';box.id='operation-confirm';box.setAttribute('aria-labelledby','operation-confirm-title');box.innerHTML=`<div class="operation-confirm-icon" aria-hidden="true">✓</div><h2 id="operation-confirm-title">${esc(options.title||'请确认操作')}</h2><dl>${(options.rows||[]).map(([name,value])=>`<div><dt>${esc(name)}：</dt><dd data-no-i18n>${esc(value??'—')}</dd></div>`).join('')}</dl>${options.note?`<p class="operation-confirm-note">${esc(options.note)}</p>`:''}${options.comment?`<label class="confirmation-comment">${esc(options.commentLabel||(options.commentRequired?'驳回原因（必填）':'审批说明（选填）'))}<textarea id="operation-confirm-comment" maxlength="${options.commentMax||1000}" ${options.commentRequired?'required':''}>${esc(options.commentValue||'')}</textarea></label>`:''}<div class="operation-confirm-actions"><button type="button" class="button secondary" id="operation-confirm-cancel">取消</button><button type="button" class="button primary" id="operation-confirm-accept">确认</button></div>`;
 let settled=false;const finish=value=>{if(settled)return;settled=true;box.close();box.remove();if(trigger?.isConnected)trigger.focus({preventScroll:true});resolve(value);};document.body.append(box);box.querySelector('#operation-confirm-cancel').onclick=()=>finish(false);box.querySelector('#operation-confirm-accept').onclick=()=>{const field=box.querySelector('#operation-confirm-comment');if(field&&!field.reportValidity())return;if(field)options.onComment?.(field.value.trim());finish(true);};box.oncancel=e=>{e.preventDefault();finish(false);};box.addEventListener('click',e=>{const r=box.getBoundingClientRect();if(e.target===box&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))finish(false);});box.showModal();I18n.apply();box.querySelector('#operation-confirm-cancel').focus();});const promise=this.queue.then(run,run);this.queue=promise.then(()=>{});return promise;}};
